// Seed function to initialize localStorage if not already present
function initDummyData(forceReset = false) {
  const isInitialized = StorageService.get('initialized');
  if (isInitialized && !forceReset) return;

  StorageService.save('branches', InitialData.branches);
  StorageService.save('suppliers', InitialData.suppliers);
  StorageService.save('customers', InitialData.customers);
  StorageService.save('newGadgets', InitialData.newGadgets);
  StorageService.save('usedGadgets', InitialData.usedGadgets);
  StorageService.save('spareParts', InitialData.spareParts);
  StorageService.save('repairs', InitialData.repairs);
  StorageService.save('refurbishments', InitialData.refurbishments);
  StorageService.save('tradeIns', InitialData.tradeIns);
  StorageService.save('sales', InitialData.sales);
  StorageService.save('purchaseOrders', InitialData.purchaseOrders);
  StorageService.save('purchaseInvoices', InitialData.purchaseInvoices);
  StorageService.save('grns', InitialData.grns);
  StorageService.save('stockAdjustments', InitialData.stockAdjustments);
  StorageService.save('loyaltyTransactions', InitialData.loyaltyTransactions);
  StorageService.save('branchTransfers', InitialData.branchTransfers);

  // Default settings
  if (!StorageService.get('settings') || forceReset) {
    StorageService.saveSettings({
      companyName: 'GadgetPro ERP & Retail',
      currency: 'USD',
      taxRate: 5,
      defaultBranch: 'BR-001',
      lowStockThreshold: 5,
      slowMovingDays: 90,
      loyaltyRate: 1,
      theme: 'light'
    });
  }

  StorageService.save('initialized', true);
  console.log('Dummy data initialized successfully.');
}
